CREATE TABLE auth.app_user(id uuid PRIMARY KEY, username varchar(100) UNIQUE NOT NULL, password_hash varchar(100) NOT NULL, display_name varchar(200) NOT NULL, settings jsonb NOT NULL DEFAULT '{}', version bigint NOT NULL DEFAULT 0);
CREATE TABLE core.company(id uuid PRIMARY KEY, inn varchar(12) UNIQUE NOT NULL, name varchar(200) NOT NULL, registered_at date NOT NULL, profile jsonb NOT NULL DEFAULT '{}', version bigint NOT NULL DEFAULT 0);
CREATE TABLE auth.membership(user_id uuid REFERENCES auth.app_user, company_id uuid REFERENCES core.company, PRIMARY KEY(user_id,company_id));
CREATE TABLE core.product(id varchar(30) NOT NULL, version int NOT NULL, name varchar(100) NOT NULL, min_minor bigint NOT NULL, max_minor bigint NOT NULL, min_months int NOT NULL, max_months int NOT NULL, annual_rate numeric(8,6) NOT NULL, min_age_months int NOT NULL, burden_limit numeric(5,4) NOT NULL, PRIMARY KEY(id,version));
CREATE TABLE core.application(id uuid PRIMARY KEY, company_id uuid NOT NULL REFERENCES core.company, applicant_id uuid NOT NULL REFERENCES auth.app_user, product_id varchar(30) NOT NULL, product_version int NOT NULL, status varchar(40) NOT NULL, processing_state varchar(20) NOT NULL DEFAULT 'IDLE', current_revision int NOT NULL DEFAULT 0, version bigint NOT NULL DEFAULT 0, draft jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(product_id,product_version) REFERENCES core.product);
CREATE INDEX ON core.application(company_id,created_at);
CREATE TABLE core.document(id uuid PRIMARY KEY, company_id uuid NOT NULL REFERENCES core.company, uploaded_by uuid NOT NULL REFERENCES auth.app_user, object_key varchar(200) UNIQUE NOT NULL, checksum varchar(64) NOT NULL, kind varchar(30) NOT NULL, content_type varchar(100) NOT NULL, filename varchar(200) NOT NULL, size bigint NOT NULL CHECK(size>0 AND size<=10485760), metadata jsonb NOT NULL, state varchar(20) NOT NULL DEFAULT 'PENDING', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE core.application_revision(application_id uuid NOT NULL REFERENCES core.application, revision int NOT NULL CHECK(revision>0), snapshot jsonb NOT NULL, payload_hash varchar(64) NOT NULL, frozen_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(application_id,revision));
CREATE TABLE core.revision_document(application_id uuid NOT NULL, revision int NOT NULL, document_id uuid NOT NULL REFERENCES core.document, PRIMARY KEY(application_id,revision,document_id), FOREIGN KEY(application_id,revision) REFERENCES core.application_revision);
CREATE TABLE core.check_result(id uuid PRIMARY KEY, application_id uuid NOT NULL, revision int NOT NULL, outcome varchar(30) NOT NULL, reasons jsonb NOT NULL, completed_at timestamptz NOT NULL DEFAULT now(), UNIQUE(application_id,revision), FOREIGN KEY(application_id,revision) REFERENCES core.application_revision);
CREATE TABLE core.external_snapshot(application_id uuid NOT NULL, revision int NOT NULL, source varchar(30) NOT NULL, fixture_version varchar(50) NOT NULL, response_hash varchar(64) NOT NULL, response jsonb NOT NULL, completed_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(application_id,revision,source), FOREIGN KEY(application_id,revision) REFERENCES core.application_revision);
CREATE TABLE core.assessment_request(request_id uuid PRIMARY KEY, application_id uuid NOT NULL, revision int NOT NULL, input_hash varchar(64) NOT NULL, provider varchar(30) NOT NULL, model_version varchar(60) NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(application_id,revision), FOREIGN KEY(application_id,revision) REFERENCES core.application_revision);
CREATE TABLE core.assessment(id uuid PRIMARY KEY, request_id uuid UNIQUE NOT NULL REFERENCES core.assessment_request, application_id uuid NOT NULL, revision int NOT NULL, result jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(application_id,revision) REFERENCES core.application_revision);
CREATE TABLE core.decision(id uuid PRIMARY KEY, application_id uuid NOT NULL, revision int NOT NULL, assessment_id uuid UNIQUE NOT NULL REFERENCES core.assessment, rule_version varchar(50) NOT NULL, product_version int NOT NULL, outcome varchar(30) NOT NULL, reasons jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(application_id,revision), FOREIGN KEY(application_id,revision) REFERENCES core.application_revision);
CREATE TABLE core.info_request(id uuid PRIMARY KEY, application_id uuid NOT NULL REFERENCES core.application, revision int NOT NULL, fields jsonb NOT NULL, answered_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE core.offer(id uuid PRIMARY KEY, application_id uuid UNIQUE NOT NULL REFERENCES core.application, revision int NOT NULL, amount_minor bigint NOT NULL CHECK(amount_minor>0), term_months int NOT NULL, annual_rate numeric(8,6) NOT NULL, monthly_payment_minor bigint NOT NULL, counteroffer boolean NOT NULL, expires_at timestamptz NOT NULL, status varchar(20) NOT NULL DEFAULT 'OPEN');
CREATE TABLE core.contract(id uuid PRIMARY KEY, offer_id uuid UNIQUE NOT NULL REFERENCES core.offer, application_id uuid UNIQUE NOT NULL REFERENCES core.application, text_content text NOT NULL, signed_at timestamptz);
CREATE TABLE core.simulated_ledger_entry(id uuid PRIMARY KEY, contract_id uuid UNIQUE NOT NULL REFERENCES core.contract, amount_minor bigint NOT NULL, simulated boolean NOT NULL DEFAULT true CHECK(simulated), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE core.status_event(id bigserial PRIMARY KEY, application_id uuid NOT NULL REFERENCES core.application, revision int NOT NULL, from_status varchar(40), to_status varchar(40) NOT NULL, reason varchar(100) NOT NULL, actor_type varchar(20) NOT NULL, actor_id varchar(100), trace_id varchar(64) NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE core.command(user_id uuid NOT NULL REFERENCES auth.app_user, command_id uuid NOT NULL, payload_hash varchar(64) NOT NULL, result_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,command_id));
CREATE TABLE core.inbox_event(event_id uuid PRIMARY KEY, payload_hash varchar(64) NOT NULL, disposition varchar(20) NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE core.audit_event(id bigserial PRIMARY KEY, actor varchar(100) NOT NULL, action varchar(100) NOT NULL, resource_id uuid, trace_id varchar(64) NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE auth.spring_session(primary_id char(36) PRIMARY KEY, session_id char(36) NOT NULL UNIQUE, creation_time bigint NOT NULL, last_access_time bigint NOT NULL, max_inactive_interval int NOT NULL, expiry_time bigint NOT NULL, principal_name varchar(100));
CREATE INDEX ON auth.spring_session(expiry_time);
CREATE INDEX ON auth.spring_session(principal_name);
CREATE TABLE auth.spring_session_attributes(session_primary_id char(36) NOT NULL REFERENCES auth.spring_session(primary_id) ON DELETE CASCADE, attribute_name varchar(200) NOT NULL, attribute_bytes bytea NOT NULL, PRIMARY KEY(session_primary_id,attribute_name));
